import pathlib,json,hashlib,shutil,subprocess,datetime,os
p=json.loads("{\"app\":\"\\\"use strict\\\";\\nconst $ = id => document.getElementById(id);\\nlet current = null;\\nasync function request(path, value) {\\n  const options = value === undefined ? {} : {method:\\\"POST\\\",headers:{\\\"Content-Type\\\":\\\"application/json\\\"},body:JSON.stringify(value)};\\n  const response = await fetch(path, options), data = await response.json();\\n  if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);\\n  return data;\\n}\\nfunction svgElement(tag, attrs, text) {\\n  const node = document.createElementNS(\\\"http://www.w3.org/2000/svg\\\", tag);\\n  for (const [k,v] of Object.entries(attrs)) node.setAttribute(k,v);\\n  if (text !== undefined) node.textContent = text;\\n  return node;\\n}\\nfunction plot(id, state, minute) {\\n  const svg = $(id); svg.replaceChildren();\\n  const X = x => 50 + (x+6)*35, Y = y => 325-y*26;\\n  for (let x=-6;x<=6;x+=2) {\\n    svg.append(svgElement(\\\"line\\\",{x1:X(x),y1:25,x2:X(x),y2:325,stroke:\\\"#293952\\\"}));\\n    svg.append(svgElement(\\\"text\\\",{x:X(x),y:348,\\\"text-anchor\\\":\\\"middle\\\"},x));\\n  }\\n  for (let y=0;y<=10;y+=2) {\\n    svg.append(svgElement(\\\"line\\\",{x1:50,y1:Y(y),x2:470,y2:Y(y),stroke:\\\"#293952\\\"}));\\n    svg.append(svgElement(\\\"text\\\",{x:34,y:Y(y)+5,\\\"text-anchor\\\":\\\"end\\\"},y));\\n  }\\n  svg.append(svgElement(\\\"text\\\",{x:255,y:377,\\\"text-anchor\\\":\\\"middle\\\"},\\\"x / nautical miles (synthetic)\\\"));\\n  svg.append(svgElement(\\\"text\\\",{x:50,y:18},\\\"y / nm • both at 10,000 fixture ft\\\"));\\n  state.aircraft.forEach((a,index) => {\\n    const color = index===0 ? \\\"#74d7cf\\\" : \\\"#eec277\\\";\\n    svg.append(svgElement(\\\"line\\\",{x1:X(a.x_nm),y1:Y(a.y_nm),x2:X(a.x_nm+a.vx_nm_min*5),y2:Y(a.y_nm+a.vy_nm_min*5),stroke:color,\\\"stroke-width\\\":3,\\\"stroke-dasharray\\\":\\\"6 5\\\"}));\\n    const x=X(a.x_nm+a.vx_nm_min*minute),y=Y(a.y_nm+a.vy_nm_min*minute);\\n    svg.append(svgElement(\\\"circle\\\",{cx:x,cy:y,r:8,fill:color}));\\n    svg.append(svgElement(\\\"text\\\",{x:Math.min(430,Math.max(60,x+12)),y:Math.max(42,y-14),fill:color},a.aircraft_id));\\n  });\\n}\\nfunction plots() {\\n  if (!current) return;\\n  const minute = Number($(\\\"minute\\\").value);\\n  $(\\\"minute-label\\\").value = `${minute.toFixed(1)} min`;\\n  plot(\\\"before\\\", current.before, minute); plot(\\\"after\\\", current.after, minute);\\n}\\nfunction render(data) {\\n  current=data; $(\\\"result\\\").hidden=false; $(\\\"export\\\").disabled=false;\\n  $(\\\"outcome\\\").textContent = data.outcome===\\\"rejected\\\" ? \\\"Rejected · no simulated actuation\\\" : \\\"Fixture accepted · simulated actuation only\\\";\\n  $(\\\"outcome\\\").className = data.outcome===\\\"rejected\\\" ? \\\"rejected\\\" : \\\"\\\";\\n  $(\\\"reason\\\").textContent = data.rejection_reason ? `Engine reason: ${data.rejection_reason}` : \\\"Exact-hash fixture approval and acknowledgement passed the engine gates.\\\";\\n  $(\\\"conflicts\\\").textContent = `Projected conflict: before ${data.before_conflict} → after ${data.after_conflict}`;\\n  $(\\\"clock\\\").textContent = `Observation ${data.simulation_clock.observed_sec}s · dispatch ${data.simulation_clock.dispatch_sec}s (synthetic)`;\\n  $(\\\"after-title\\\").textContent = data.outcome===\\\"rejected\\\" ? \\\"After rejection · unchanged world\\\" : \\\"After simulated advisory\\\";\\n  $(\\\"advisory\\\").textContent=JSON.stringify({advisory:data.advisory,advisory_hash:data.advisory_hash,fixtures:data.fixtures},null,2);\\n  $(\\\"chain\\\").textContent=`Local chain valid: ${data.audit_valid} · head ${data.audit_head}`;\\n  $(\\\"timeline\\\").replaceChildren();\\n  data.audit_events.forEach(event => {\\n    const li=document.createElement(\\\"li\\\"),title=document.createElement(\\\"strong\\\"),payload=document.createElement(\\\"pre\\\");\\n    title.textContent=`${event.seq+1}. ${event.kind}`; payload.textContent=JSON.stringify(event.payload,null,2);\\n    li.append(title,payload); $(\\\"timeline\\\").append(li);\\n  });\\n  $(\\\"minute\\\").value=0; plots();\\n}\\n$(\\\"scenario\\\").addEventListener(\\\"change\\\",()=> {\\n  $(\\\"description\\\").textContent=$(\\\"scenario\\\").selectedOptions[0].dataset.description;\\n  $(\\\"status\\\").textContent=\\\"Selection changed. Run to produce a new result; displayed result still belongs to the previous run.\\\";\\n});\\n$(\\\"minute\\\").addEventListener(\\\"input\\\",plots);\\n$(\\\"run\\\").addEventListener(\\\"click\\\",async()=> {\\n  $(\\\"run\\\").disabled=true; $(\\\"status\\\").textContent=\\\"Running local deterministic fixture…\\\";\\n  try {\\n    const data=await request(\\\"/api/run\\\",{scenario:$(\\\"scenario\\\").value,include_approval:$(\\\"approval\\\").checked,include_ack:$(\\\"ack\\\").checked});\\n    render(data); $(\\\"status\\\").textContent=`Result: ${data.label}. ${data.disclaimer}`;\\n  } catch(e) {$(\\\"status\\\").textContent=`Run failed: ${e.message}`;}\\n  finally {$(\\\"run\\\").disabled=false;}\\n});\\n$(\\\"export\\\").addEventListener(\\\"click\\\",()=> {\\n  if (!current) return;\\n  const url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:\\\"application/json\\\"}));\\n  const a=document.createElement(\\\"a\\\"); a.href=url; a.download=`towerops-${current.request.scenario}.json`; a.click();\\n  setTimeout(()=>URL.revokeObjectURL(url),1000);\\n});\\nlet replaySelection = null;\\n$(\\\"replay-file\\\").addEventListener(\\\"change\\\",async()=> {\\n  const selection = {};\\n  replaySelection = selection;\\n  const file=$(\\\"replay-file\\\").files[0];\\n  if (!file) {$(\\\"replay-status\\\").textContent=\\\"\\\";return;}\\n  $(\\\"replay-status\\\").textContent=\\\"Replaying locally…\\\";\\n  try {\\n    if(file.size>262144) throw new Error(\\\"Export exceeds 262144 bytes\\\");\\n    const text=await file.text();\\n    if (replaySelection !== selection) return;\\n    const value=JSON.parse(text),reply=await request(\\\"/api/replay\\\",value);\\n    if (replaySelection !== selection) return;\\n    $(\\\"replay-status\\\").textContent = reply.matches ? `Replay MATCH: ${reply.outcome}. ${reply.note}` : `Replay MISMATCH: export differs from the deterministic engine result. ${reply.note}`;\\n  } catch(e) {\\n    if (replaySelection === selection) $(\\\"replay-status\\\").textContent=`Replay rejected: ${e.message}`;\\n  }\\n});\\nrequest(\\\"/api/scenarios\\\").then(data=> {\\n  data.scenarios.forEach(item=> {const option=document.createElement(\\\"option\\\"); option.value=item.id;option.textContent=item.label;option.dataset.description=item.description;$(\\\"scenario\\\").append(option);});\\n  $(\\\"description\\\").textContent=data.scenarios[0].description;\\n  $(\\\"status\\\").textContent=\\\"Ready. Choose a case, then run the simulated fixtures.\\\";\\n}).catch(e=> {$(\\\"status\\\").textContent=`Load failed: ${e.message}`;$(\\\"run\\\").disabled=true;});\\n\",\"doc\":\"# TowerOps local synthetic scenario explorer\\n\\nResearch simulation only; fixture identities are not real authority. No live feeds, model/Strands calls, SDK dependency, real clearances, or aviation safety claim. Existing `towerops.py` is byte-for-byte unchanged from public baseline `e8fa18e`.\\n\\n## First run\\n\\nPython 3.12+ and a modern browser; **no pip install is needed for the app**.\\n\\n```sh\\npython explorer.py serve --port 8765\\n```\\n\\nOpen http://127.0.0.1:8765 . Choose **Approval + acknowledgement**, leave the two simulated-fixture boxes checked, and Run. The projected conflict changes true→false after simulated actuation. Scrub projected minutes to compare constant-velocity paths. Gate times are synthetic seconds, separate from projected minutes.\\n\\nChoose **Missing acknowledgement** and Run without reloading: rejection `ack_missing`, unchanged world, no actuation event. The displayed result and download always represent the last completed run, not an unrun selection. Withholding checkboxes cannot supply missing fixtures or bypass engine gates.\\n\\nOther fixed cases: missing approval, acknowledgement dated after dispatch cutoff (`ack_late`), stale observation, changed world hash, acknowledgement for wrong advisory, expired proposal. Every refusal retains the exact pre-gate world. Fixed identities are `FIXTURE-A`, `FIXTURE-B`, `FIXTURE-CONTROLLER-NOT-AUTHORITY`.\\n\\n## Export and replay\\n\\nExport JSON after a run. Select that file under **Replay exported JSON**: the backend reexecutes its fixed scenario and fixture switches and compares the entire result. It accepts equivalent finite JSON numbers (1001 versus 1001.0), never boolean→number coercion. Change `after.version` in a copy and replay: MISMATCH. Malformed formats/unknown scenarios are rejected. Uploaded files are not saved or used as arbitrary engine input.\\n\\nThe replay status belongs to the currently selected file. Selecting another export retires earlier file reads and replay responses, including their errors; clearing the input clears the status. An already-sent request may still finish, but cannot replace the newer verdict. Replay does not change the displayed scenario result or its JSON export.\\n\\nReplay is reproducibility under this local engine, not authenticity. The hash chain is not a signature or external custody anchor; someone can construct another valid fixed-fixture export. No replay result grants real authority.\\n\\nCLI (shell redirection saves real engine output):\\n\\n```sh\\npython explorer.py run approved > approved.json\\npython explorer.py run missing_ack > missing_ack.json\\npython explorer.py run approved --without-approval\\npython explorer.py replay approved.json\\n```\\n\\nReplay exits 0 for match, 1 for mismatch, 2 for malformed input.\\n\\n## Tests\\n\\nStandard-library engine/control + real HTTP suite:\\n\\n```sh\\npython -m unittest -v test_explorer\\n```\\n\\nIt exercises all eight cases × four fixture-switch combinations, exact no-actuation retention, full-export edits, JS numeric roundtrip, real HTTP run/replay, and invalid requests. No fabricated provider outputs.\\n\\nFocused Explorer replay-selection lifecycle tests (Node.js 20+; built-in modules only):\\n\\n```sh\\nnode tests/test_explorer_replay_selection.cjs\\n```\\n\\nThese controlled DOM/fetch tests cover superseded reads, responses, JSON bodies and errors, same-file reselection, clearing, current refusals and explicit recovery. They do not replace actual browser receiving.\\n\\nOptional actual browser acceptance:\\n\\n```sh\\npython -m pip install playwright\\npython -m playwright install chromium\\n# Linux images without browser libraries only:\\npython -m playwright install-deps chromium\\npython browser_acceptance.py\\n```\\n\\nChromium exercises all eight UI cases at desktop 1280×900 and mobile 390×844, sliders/SVG geometry, downloads, original replay, tampered replay, withheld controls, no horizontal overflow/page errors. Browser dependencies are test-only, not app dependencies. Logs/screenshots live in local `evidence/` when that directory exists.\\n\\n## HTTP scope\\n\\nBound to 127.0.0.1 only. Static routes `/`, `/app.js`, `/style.css`; GET `/api/scenarios`; POST `/api/run` with JSON `{ \\\"scenario\\\": \\\"approved\\\", \\\"include_approval\\\": true, \\\"include_ack\\\": true }`; POST `/api/replay` with a whole exported result. Fixed inputs only, 256KiB body cap, same-origin Host/Origin checks. This is a local development server, not a remotely deployed service. Ctrl+C stops it; no estate services are touched.\\n\\n## Getting the code\\n\\nEverything needed is in this repository (standard library only for the app). Either clone the branch, or apply the patch to a clean checkout of baseline `e8fa18e` (`main`):\\n\\n```sh\\ngit apply towerops-explorer-all.patch   # from a clean clone of main\\npython -m unittest -q                   # 8 tests\\npython explorer.py serve --port 8765\\n```\\n\\nA transfer zip of the same files (`towerops-explorer.zip`) runs the same way after extraction; compare its SHA-256 with the delivery report if you move it between machines.\\n\",\"test\":\"\\\"use strict\\\";\\nconst assert = require(\\\"node:assert/strict\\\");\\nconst fs = require(\\\"node:fs\\\");\\nconst path = require(\\\"node:path\\\");\\nconst vm = require(\\\"node:vm\\\");\\nconst test = require(\\\"node:test\\\");\\n\\nconst appPath = process.argv[2] || path.join(__dirname, \\\"..\\\", \\\"web\\\", \\\"app.js\\\");\\nconst app = fs.readFileSync(appPath, \\\"utf8\\\");\\nconst tick = () => new Promise(resolve => setImmediate(resolve));\\nfunction deferred() {\\n  let resolve, reject;\\n  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });\\n  return {promise, resolve, reject};\\n}\\nfunction file(value, overrides = {}) {\\n  return {name: \\\"fixture.json\\\", size: 20, text: async () => JSON.stringify(value), ...overrides};\\n}\\nfunction reply(matches, note = \\\"current note\\\") {\\n  return {matches, outcome: \\\"rejected\\\", note};\\n}\\nfunction response(data) {\\n  return {ok: true, json: async () => data};\\n}\\nasync function harness() {\\n  const nodes = new Map();\\n  function node(id) {\\n    if (!nodes.has(id)) nodes.set(id, {\\n      id, textContent: \\\"\\\", value: \\\"\\\", disabled: false, files: [], dataset: {},\\n      children: [], listeners: {}, selectedOptions: [{dataset: {description: \\\"fixture\\\"}}],\\n      addEventListener(kind, listener) { this.listeners[kind] = listener; },\\n      append(...items) { this.children.push(...items); },\\n      replaceChildren(...items) { this.children = items; },\\n      setAttribute() {},\\n    });\\n    return nodes.get(id);\\n  }\\n  const calls = [];\\n  const context = vm.createContext({\\n    document: {getElementById: node, createElement: () => node(Symbol()),\\n      createElementNS: () => node(Symbol())},\\n    fetch: (url, options) => {\\n      if (url === \\\"/api/scenarios\\\") return Promise.resolve(response({\\n        scenarios: [{id: \\\"approved\\\", label: \\\"Approved\\\", description: \\\"fixture\\\"}],\\n      }));\\n      assert.equal(url, \\\"/api/replay\\\");\\n      const gate = deferred();\\n      calls.push({url, body: JSON.parse(options.body), gate});\\n      return gate.promise;\\n    },\\n    console, setTimeout, URL, Blob,\\n  });\\n  vm.runInContext(app, context, {filename: appPath});\\n  await tick();\\n  const unrelated = () => JSON.stringify([...nodes].filter(([id]) =>\\n    typeof id === \\\"string\\\" && id !== \\\"replay-file\\\" && id !== \\\"replay-status\\\")\\n    .map(([id, n]) => [id, n.textContent, n.value, n.disabled, n.children.length]));\\n  const before = unrelated();\\n  return {\\n    calls, context,\\n    choose(selected) {\\n      node(\\\"replay-file\\\").files = selected ? [selected] : [];\\n      return node(\\\"replay-file\\\").listeners.change();\\n    },\\n    status: () => node(\\\"replay-status\\\").textContent,\\n    preserve: () => {\\n      assert.equal(unrelated(), before, \\\"replay does not alter other controls\\\");\\n      assert.equal(vm.runInContext(\\\"current\\\", context), null, \\\"displayed run stays unchanged\\\");\\n    },\\n  };\\n}\\n\\ntest(\\\"current match and mismatch keep their existing complete messages\\\", async () => {\\n  const h = await harness();\\n  let pending = h.choose(file({id: \\\"match\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(true))); await pending;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  pending = h.choose(file({id: \\\"mismatch\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(false))); await pending;\\n  assert.equal(h.status(), \\\"Replay MISMATCH: export differs from the deterministic engine result. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded file read does not send a replay or replace the newer verdict\\\", async () => {\\n  const h = await harness(), oldRead = deferred();\\n  const old = h.choose(file({}, {text: () => oldRead.promise}));\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(false, \\\"new file\\\"))); await fresh;\\n  const accepted = h.status();\\n  oldRead.resolve(JSON.stringify({id: \\\"old\\\"})); await tick();\\n  // Settle an obsolete request if the original source issued it, without hanging the test.\\n  for (const call of h.calls.slice(1)) call.gate.resolve(response(reply(true, \\\"old file\\\")));\\n  await old;\\n  assert.equal(h.calls.length, 1, \\\"old read must not reach the backend\\\");\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded file read error cannot replace current pending or completed status\\\", async () => {\\n  const h = await harness(), oldRead = deferred();\\n  const old = h.choose(file({}, {text: () => oldRead.promise}));\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  oldRead.reject(new Error(\\\"old read error\\\")); await old;\\n  assert.equal(h.status(), \\\"Replaying locally…\\\");\\n  h.calls[0].gate.resolve(response(reply(true))); await fresh;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded HTTP response cannot replace a newer mismatch\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(false, \\\"new file\\\"))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.resolve(response(reply(true, \\\"old file\\\"))); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded JSON body cannot replace a newer rejection\\\", async () => {\\n  const h = await harness(), body = deferred();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  h.calls[0].gate.resolve({ok: true, json: () => body.promise}); await tick();\\n  await h.choose(file({}, {text: async () => \\\"{\\\"}));\\n  const accepted = h.status();\\n  assert.match(accepted, /^Replay rejected:/);\\n  body.resolve(reply(true, \\\"old body\\\")); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded transport error cannot replace a newer match\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(true))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.reject(new Error(\\\"old network error\\\")); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"clearing selection retires an in-flight response and clears its status\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  await h.choose(null);\\n  assert.equal(h.status(), \\\"\\\");\\n  h.calls[0].gate.resolve(response(reply(true))); await old;\\n  assert.equal(h.status(), \\\"\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"selecting the same File again retires its earlier request\\\", async () => {\\n  const h = await harness(), same = file({id: \\\"same\\\"});\\n  const old = h.choose(same); await tick();\\n  const fresh = h.choose(same); await tick();\\n  h.calls[1].gate.resolve(response(reply(false, \\\"latest attempt\\\"))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.resolve(response(reply(true, \\\"earlier attempt\\\"))); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a current oversize or read failure refuses, and an explicit corrected selection recovers\\\", async () => {\\n  const h = await harness();\\n  await h.choose(file({}, {size: 262145, text: () => { throw new Error(\\\"must not read\\\"); }}));\\n  assert.equal(h.status(), \\\"Replay rejected: Export exceeds 262144 bytes\\\");\\n  assert.equal(h.calls.length, 0);\\n  await h.choose(file({}, {text: async () => { throw new Error(\\\"current read error\\\"); }}));\\n  assert.equal(h.status(), \\\"Replay rejected: current read error\\\");\\n  const fresh = h.choose(file({id: \\\"corrected\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(true))); await fresh;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a current backend refusal retains the existing error display\\\", async () => {\\n  const h = await harness();\\n  const pending = h.choose(file({id: \\\"current\\\"})); await tick();\\n  h.calls[0].gate.resolve({ok: false, status: 400, json: async () => ({error: \\\"current server refusal\\\"})});\\n  await pending;\\n  assert.equal(h.status(), \\\"Replay rejected: current server refusal\\\");\\n  h.preserve();\\n});\\n\"}")
